import React, { useEffect, useState } from 'react';
import { View, Text, TouchableOpacity, ScrollView, Image, Modal, TextInput, StyleSheet, Alert } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as ImagePicker from 'expo-image-picker';
import { VideoView, useVideoPlayer } from 'expo-video';
import { useRouter } from 'expo-router';
import { collection, query, where, orderBy, onSnapshot, addDoc, setDoc, doc, updateDoc, arrayUnion, serverTimestamp } from 'firebase/firestore';
import { auth, db } from '../config';
import { useTheme, BRAND } from './theme';

export { CommentModal } from './CommentModal';

const CLOUD_NAME = 'faqfo0lu';
const UPLOAD_PRESET = 'flevora_upload';

function StoryVideo({ uri }: { uri: string }) {
  const player = useVideoPlayer(uri, (p) => { p.loop = true; p.play(); });
    return <VideoView player={player} style={styles.storyMedia} nativeControls={false} />;
    }

    export function FeedHeader() {
      const router = useRouter();
        const { c } = useTheme();
          const uid = auth.currentUser?.uid || '';
            const [me, setMe] = useState<any>(null);
              const [stories, setStories] = useState<any[]>([]);
                const [activeIdx, setActiveIdx] = useState<number | null>(null);
                  const [progress, setProgress] = useState(0);
                    const [showViewers, setShowViewers] = useState(false);
                      const [reply, setReply] = useState('');
                        const [hasUnread, setHasUnread] = useState(false);

                          useEffect(() => {
                              const u1 = onSnapshot(query(collection(db, 'stories'), orderBy('createdAt', 'desc')), (snap) => {
                                    const now = Date.now();
                                          const list = snap.docs.map((d) => ({ id: d.id, ...d.data() })).filter((s: any) => {
                                                  if (s.expiresAt && s.expiresAt <= now) return false;
                                                          if (s.closeFriendsOnly) return s.uid === uid || (Array.isArray(s.allowedUids) && s.allowedUids.includes(uid));
                                                                  return true;
                                                                        });
                                                                              setStories(list);
                                                                                  });
                                                                                      if (!uid) return u1;
                                                                                          const u2 = onSnapshot(query(collection(db, 'notifications'), where('toUid', '==', uid), where('read', '==', false)), (s) => {
                                                                                                setHasUnread(!s.empty);
                                                                                                    }, () => {});
                                                                                                        const u3 = onSnapshot(doc(db, 'users', uid), (s) => { if (s.exists()) setMe(s.data()); });
                                                                                                            return () => { u1(); u2(); u3(); };
                                                                                                              }, [uid]);

                                                                                                                useEffect(() => {
                                                                                                                    if (activeIdx === null || showViewers) return;
                                                                                                                        setProgress(0);
                                                                                                                            const timer = setInterval(() => {
                                                                                                                                  setProgress((p) => {
                                                                                                                                          if (p >= 100) {
                                                                                                                                                    if (activeIdx < stories.length - 1) openStory(activeIdx + 1);
                                                                                                                                                              else setActiveIdx(null);
                                                                                                                                                                        return 0;
                                                                                                                                                                                }
                                                                                                                                                                                        return p + 2;
                                                                                                                                                                                              });
                                                                                                                                                                                                  }, 100);
                                                                                                                                                                                                      return () => clearInterval(timer);
                                                                                                                                                                                                        }, [activeIdx, showViewers, stories.length]);

                                                                                                                                                                                                          const askStoryAudience = () => {
                                                                                                                                                                                                              Alert.alert('New Story', 'Who can view this story?', [
                                                                                                                                                                                                                    { text: 'Everyone', onPress: () => uploadStory(false) },
                                                                                                                                                                                                                          { text: 'Close Friends ★', onPress: () => uploadStory(true) },
                                                                                                                                                                                                                                { text: 'Cancel', style: 'cancel' },
                                                                                                                                                                                                                                    ]);
                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                        const uploadStory = async (cfOnly: boolean) => {
                                                                                                                                                                                                                                            const res = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images', 'videos'], quality: 0.7 });
                                                                                                                                                                                                                                                if (res.canceled || !res.assets[0] || !uid) return;
                                                                                                                                                                                                                                                    const asset = res.assets[0];
                                                                                                                                                                                                                                                        const type = asset.type === 'video' ? 'video' : 'image';
                                                                                                                                                                                                                                                            const data = new FormData();
                                                                                                                                                                                                                                                                data.append('file', { uri: asset.uri, type: type === 'video' ? 'video/mp4' : 'image/jpeg', name: `story_${Date.now()}` } as any);
                                                                                                                                                                                                                                                                    data.append('upload_preset', UPLOAD_PRESET);
                                                                                                                                                                                                                                                                        const xhr = new XMLHttpRequest();
                                                                                                                                                                                                                                                                            xhr.open('POST', `https://api.cloudinary.com/v1_1/${CLOUD_NAME}/${type}/upload`);
                                                                                                                                                                                                                                                                                xhr.onload = async () => {
                                                                                                                                                                                                                                                                                      const json = JSON.parse(xhr.responseText);
                                                                                                                                                                                                                                                                                            if (!json.secure_url) return;
                                                                                                                                                                                                                                                                                                  await addDoc(collection(db, 'stories'), {
                                                                                                                                                                                                                                                                                                          uid, username: me?.username || 'user', mediaUrl: json.secure_url, mediaType: type,
                                                                                                                                                                                                                                                                                                                  closeFriendsOnly: cfOnly, allowedUids: cfOnly ? (me?.closeFriends || []) : [],
                                                                                                                                                                                                                                                                                                                          viewers: [], viewerNames: [], expiresAt: Date.now() + 86400000, createdAt: serverTimestamp(),
                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                        xhr.send(data);
                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                            const openStory = async (i: number) => {
                                                                                                                                                                                                                                                                                                                                                setShowViewers(false); setActiveIdx(i);
                                                                                                                                                                                                                                                                                                                                                    if (stories[i] && uid) {
                                                                                                                                                                                                                                                                                                                                                          updateDoc(doc(db, 'stories', stories[i].id), { viewers: arrayUnion(uid), viewerNames: arrayUnion(me?.username || 'user') }).catch(() => {});
                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                  const sendStoryMsg = async (txt: string, type: 'reply' | 'reaction') => {
                                                                                                                                                                                                                                                                                                                                                                      if (activeIdx === null || !txt.trim() || !uid) return;
                                                                                                                                                                                                                                                                                                                                                                          const st = stories[activeIdx];
                                                                                                                                                                                                                                                                                                                                                                              const chatId = [uid, st.uid].sort().join('_');
                                                                                                                                                                                                                                                                                                                                                                                  await setDoc(doc(db, 'conversations', chatId), { participants: [uid, st.uid], updatedAt: serverTimestamp() }, { merge: true });
                                                                                                                                                                                                                                                                                                                                                                                      await addDoc(collection(db, 'conversations', chatId, 'messages'), {
                                                                                                                                                                                                                                                                                                                                                                                            senderUid: uid, text: type === 'reaction' ? `Reacted ${txt} to your story` : `Story reply: ${txt}`,
                                                                                                                                                                                                                                                                                                                                                                                                  mediaType: 'text', read: false, createdAt: serverTimestamp(),
                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                          await addDoc(collection(db, 'notifications'), {
                                                                                                                                                                                                                                                                                                                                                                                                                toUid: st.uid, fromUid: uid, fromUsername: me?.username || 'user',
                                                                                                                                                                                                                                                                                                                                                                                                                      type: 'reply', message: type === 'reaction' ? `reacted ${txt} to your story` : `replied: ${txt}`,
                                                                                                                                                                                                                                                                                                                                                                                                                            read: false, createdAt: serverTimestamp(),
                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                                                                                                                                                                                                    const active = activeIdx !== null ? stories[activeIdx] : null;

                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                          <View style={{ backgroundColor: c.background }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                <View style={[styles.topBar, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                        <TouchableOpacity hitSlop={14} onPress={() => router.push('/upload' as any)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Ionicons name="add" size={28} color={c.text} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={styles.logo}>Flevora</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity hitSlop={14} onPress={() => router.push('/notification' as any)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Ionicons name="heart-outline" size={25} color={c.text} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {hasUnread && <View style={styles.dot} />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <ScrollView horizontal showsHorizontalScrollIndicator={false} style={[styles.storyBar, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity style={styles.storyItem} onPress={askStoryAudience}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {me?.avatar ? <Image source={{ uri: me.avatar }} style={styles.myStoryImg} /> : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={[styles.myStoryImg, { backgroundColor: BRAND, justifyContent: 'center', alignItems: 'center' }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={{ color: '#fff', fontSize: 22, fontWeight: '700' }}>{(me?.username || 'F')[0].toUpperCase()}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={[styles.addBadge, { borderColor: c.background }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Ionicons name="add" size={14} color="#fff" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={[styles.storyName, { color: c.text }]}>Your story</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </TouchableOpacity>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {stories.map((s, i) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const thumb = s.mediaType === 'video' ? (s.mediaUrl || '').replace(/\.(mp4|mov|webm)$/i, '.jpg') : s.mediaUrl;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity key={s.id} style={styles.storyItem} onPress={() => openStory(i)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <View style={[styles.storyRing, { borderColor: s.closeFriendsOnly ? '#10B981' : BRAND }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Image source={{ uri: thumb }} style={styles.storyThumb} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={[styles.storyName, { color: c.text }]} numberOfLines={1}>{s.username}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </ScrollView>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Modal visible={!!active} animationType="fade">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={styles.modal}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {active?.mediaType === 'video' ? <StoryVideo uri={active.mediaUrl} /> : <Image source={{ uri: active?.mediaUrl }} style={styles.storyMedia} />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={styles.progBg}><View style={[styles.progFill, { width: `${progress}%` }]} /></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={styles.storyTop}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <TouchableOpacity onPress={() => active?.uid === uid && setShowViewers((v) => !v)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={{ color: '#fff', fontWeight: '700' }}>@{active?.username} • {active?.viewers?.length || 0} views {active?.uid === uid ? '▾' : ''}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity onPress={() => setActiveIdx(null)}><Ionicons name="close" size={28} color="#fff" /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {showViewers && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={styles.viewerBox}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={{ color: '#fff', fontWeight: '700', marginBottom: 6 }}>Viewers</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {(active?.viewerNames || []).map((n: string, idx: number) => <Text key={idx} style={{ color: '#E5E7EB', paddingVertical: 2 }}>@{n}</Text>)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <View style={styles.navOverlay}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TouchableOpacity style={{ flex: 1 }} onPress={() => activeIdx! > 0 && openStory(activeIdx! - 1)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity style={{ flex: 1 }} onPress={() => activeIdx! < stories.length - 1 ? openStory(activeIdx! + 1) : setActiveIdx(null)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <View style={styles.replyBar}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TextInput style={styles.replyInput} placeholder="Reply..." placeholderTextColor="#ccc" value={reply} onChangeText={setReply} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {['❤️', '🔥', '😂'].map((e) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity key={e} onPress={() => sendStoryMsg(e, 'reaction')}><Text style={{ fontSize: 20 }}>{e}</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity onPress={() => { sendStoryMsg(reply, 'reply'); setReply(''); }}><Ionicons name="send" size={22} color="#fff" /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </Modal>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const styles = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    topBar: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: 16, paddingTop: 48, paddingBottom: 10, borderBottomWidth: 1 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      logo: { fontSize: 24, fontWeight: '800', color: BRAND },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dot: { width: 8, height: 8, borderRadius: 4, backgroundColor: '#EF4444', position: 'absolute', top: 0, right: 0 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          storyBar: { paddingVertical: 10, paddingHorizontal: 12, borderBottomWidth: 1 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            storyItem: { alignItems: 'center', marginRight: 14, width: 64 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              myStoryImg: { width: 58, height: 58, borderRadius: 29 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                addBadge: { position: 'absolute', bottom: 0, right: 0, width: 20, height: 20, borderRadius: 10, backgroundColor: '#111827', borderWidth: 2, justifyContent: 'center', alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  storyRing: { width: 60, height: 60, borderRadius: 30, borderWidth: 2.5, justifyContent: 'center', alignItems: 'center', padding: 2 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    storyThumb: { width: 51, height: 51, borderRadius: 26 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      storyName: { fontSize: 11, marginTop: 4 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        modal: { flex: 1, backgroundColor: '#000', justifyContent: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          storyMedia: { width: '100%', height: '100%', resizeMode: 'contain' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            progBg: { position: 'absolute', top: 38, left: 12, right: 12, height: 3, backgroundColor: 'rgba(255,255,255,0.3)', borderRadius: 2, zIndex: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              progFill: { height: 3, backgroundColor: '#fff', borderRadius: 2 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                storyTop: { position: 'absolute', top: 50, left: 16, right: 16, flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', zIndex: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  viewerBox: { position: 'absolute', top: 90, left: 16, right: 16, backgroundColor: 'rgba(0,0,0,0.8)', padding: 14, borderRadius: 12, zIndex: 20 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    navOverlay: { position: 'absolute', top: 90, bottom: 80, left: 0, right: 0, flexDirection: 'row' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      replyBar: { position: 'absolute', bottom: 26, left: 16, right: 16, flexDirection: 'row', alignItems: 'center', gap: 10, zIndex: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        replyInput: { flex: 1, borderWidth: 1, borderColor: '#666', borderRadius: 22, paddingHorizontal: 14, paddingVertical: 8, color: '#fff' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        